### Step 2: Angle normalization, centisecond functions, and d2l

Replace the `src/math.rs` stub. 12 functions total. All are leaf functions with no internal dependencies except `midpoint_*` → `diff_degrees` → `normalize_degrees`.

Key fidelity concern: use `%` (C `fmod`), not `rem_euclid`. The `y.abs() < 1e-13` guard is the "Alois fix" from the C source — must be preserved.

```rust
use std::f64::consts::PI;
use crate::constants::{DEGTORAD, RADTODEG, TWOPI, DEG180, DEG360};

// --- Angle normalization ---

pub fn normalize_degrees(x: f64) -> f64 {
    let mut y = x % 360.0;
    if y.abs() < 1e-13 { y = 0.0; }
    if y < 0.0 { y += 360.0; }
    y
}

pub fn normalize_radians(x: f64) -> f64 {
    let mut y = x % TWOPI;
    if y.abs() < 1e-13 { y = 0.0; }
    if y < 0.0 { y += TWOPI; }
    y
}

pub(crate) fn mod_2pi(x: f64) -> f64 {
    let mut y = x % TWOPI;
    if y < 0.0 { y += TWOPI; }
    y
}

pub fn diff_degrees_norm(p1: f64, p2: f64) -> f64 {
    normalize_degrees(p1 - p2)
}

pub fn diff_degrees(p1: f64, p2: f64) -> f64 {
    let dif = normalize_degrees(p1 - p2);
    if dif >= 180.0 { dif - 360.0 } else { dif }
}

pub fn diff_radians(p1: f64, p2: f64) -> f64 {
    let dif = normalize_radians(p1 - p2);
    if dif >= PI { dif - TWOPI } else { dif }
}

pub fn midpoint_degrees(x1: f64, x0: f64) -> f64 {
    let d = diff_degrees(x1, x0);
    normalize_degrees(x0 + d / 2.0)
}

pub fn midpoint_radians(x1: f64, x0: f64) -> f64 {
    DEGTORAD * midpoint_degrees(x1 * RADTODEG, x0 * RADTODEG)
}

// --- Centisecond ---

pub fn csnorm(mut p: i32) -> i32 {
    if p < 0 {
        while p < 0 { p += DEG360; }
    } else {
        while p >= DEG360 { p -= DEG360; }
    }
    p
}

pub fn difcsn(p1: i32, p2: i32) -> i32 {
    csnorm(p1 - p2)
}

pub fn difcs2n(p1: i32, p2: i32) -> i32 {
    let dif = csnorm(p1 - p2);
    if dif >= DEG180 { dif - DEG360 } else { dif }
}

// --- Utility ---

pub fn d2l(x: f64) -> i32 {
    if x >= 0.0 {
        (x + 0.5) as i32
    } else {
        -((0.5 - x) as i32)
    }
}
```

### Step 3: Chebyshev evaluation

Two functions using the Broucke/Clenshaw algorithm (Communications of the ACM, algorithm 446). Use reverse iterator for `chebyshev_eval` to eliminate bounds checks. For `chebyshev_deriv`, the loop starts at index `ncf-1` down to `1` (needs index value for `dj = 2*j`), so use range-based loop — the compiler elides bounds checks since `j < ncf`.

```rust
pub(crate) fn chebyshev_eval(x: f64, coeffs: &[f64]) -> f64 {
    let x2 = x * 2.0;
    let mut br = 0.0;
    let mut brp2 = 0.0;
    let mut brpp = 0.0;
    for &c in coeffs.iter().rev() {
        brp2 = brpp;
        brpp = br;
        br = x2 * brpp - brp2 + c;
    }
    (br - brp2) * 0.5
}

pub(crate) fn chebyshev_deriv(x: f64, coeffs: &[f64]) -> f64 {
    let ncf = coeffs.len();
    if ncf <= 1 {
        return 0.0;
    }
    let x2 = x * 2.0;
    let mut bf = 0.0;
    let mut bj = 0.0;
    let mut xjp2 = 0.0;
    let mut xjpl = 0.0;
    let mut bjp2 = 0.0;
    let mut bjpl = 0.0;
    for j in (1..ncf).rev() {
        let dj = (j + j) as f64;
        let xj = coeffs[j] * dj + xjp2;
        bj = x2 * bjpl - bjp2 + xj;
        bf = bjp2;
        bjp2 = bjpl;
        bjpl = bj;
        xjp2 = xjpl;
        xjpl = xj;
    }
    (bj - bf) * 0.5
}
```

### Step 4: Basic coordinate transforms

4 functions. The polar singularity (rxy → 0) is handled via the exact C pattern: explicit `rxy == 0` check with ±π/2 fallback. `rotate_x` delegates to `rotate_x_sincos` after computing sin/cos.

```rust
pub(crate) fn rotate_x(pos: [f64; 3], eps: f64) -> [f64; 3] {
    let (sin_eps, cos_eps) = eps.sin_cos();
    rotate_x_sincos(pos, sin_eps, cos_eps)
}

pub(crate) fn rotate_x_sincos(pos: [f64; 3], sin_eps: f64, cos_eps: f64) -> [f64; 3] {
    [
        pos[0],
        pos[1] * cos_eps + pos[2] * sin_eps,
        -pos[1] * sin_eps + pos[2] * cos_eps,
    ]
}

pub(crate) fn cartesian_to_polar(xyz: [f64; 3]) -> [f64; 3] {
    if xyz[0] == 0.0 && xyz[1] == 0.0 && xyz[2] == 0.0 {
        return [0.0; 3];
    }
    let rxy = (xyz[0] * xyz[0] + xyz[1] * xyz[1]).sqrt();
    let dist = (xyz[0] * xyz[0] + xyz[1] * xyz[1] + xyz[2] * xyz[2]).sqrt();
    let mut lon = xyz[1].atan2(xyz[0]);
    if lon < 0.0 {
        lon += TWOPI;
    }
    let lat = if rxy == 0.0 {
        if xyz[2] >= 0.0 { PI / 2.0 } else { -(PI / 2.0) }
    } else {
        (xyz[2] / rxy).atan()
    };
    [lon, lat, dist]
}

pub(crate) fn polar_to_cartesian(lbr: [f64; 3]) -> [f64; 3] {
    let cos_lat = lbr[1].cos();
    [
        lbr[2] * cos_lat * lbr[0].cos(),
        lbr[2] * cos_lat * lbr[0].sin(),
        lbr[2] * lbr[1].sin(),
    ]
}
```

### Step 5: Speed coordinate transforms + cotrans wrappers

4 functions. `cartesian_to_polar_with_speed` is the most complex — it has the Jacobian velocity transform with three branches: zero position (use velocity direction), zero speed (delegate to position-only), and general case. `cotrans`/`cotrans_with_speed` are degree-level wrappers that compose the lower-level functions.

```rust
pub(crate) fn cartesian_to_polar_with_speed(x: [f64; 6]) -> [f64; 6] {
    if x[0] == 0.0 && x[1] == 0.0 && x[2] == 0.0 {
        let speed = (x[3] * x[3] + x[4] * x[4] + x[5] * x[5]).sqrt();
        let vel_dir = cartesian_to_polar([x[3], x[4], x[5]]);
        return [vel_dir[0], vel_dir[1], 0.0, 0.0, 0.0, speed];
    }
    if x[3] == 0.0 && x[4] == 0.0 && x[5] == 0.0 {
        let pos = cartesian_to_polar([x[0], x[1], x[2]]);
        return [pos[0], pos[1], pos[2], 0.0, 0.0, 0.0];
    }
    let rxy = (x[0] * x[0] + x[1] * x[1]).sqrt();
    let rxyz = (x[0] * x[0] + x[1] * x[1] + x[2] * x[2]).sqrt();
    let mut lon = x[1].atan2(x[0]);
    if lon < 0.0 { lon += TWOPI; }
    let lat = (x[2] / rxy).atan();
    let coslon = x[0] / rxy;
    let sinlon = x[1] / rxy;
    let coslat = rxy / rxyz;
    let sinlat = x[2] / rxyz;
    let xx3 = x[3] * coslon + x[4] * sinlon;
    let xx4 = -x[3] * sinlon + x[4] * coslon;
    let speed_lon = xx4 / rxy;
    let xx4b = -sinlat * xx3 + coslat * x[5];
    let speed_rad = coslat * xx3 + sinlat * x[5];
    let speed_lat = xx4b / rxyz;
    [lon, lat, rxyz, speed_lon, speed_lat, speed_rad]
}

pub(crate) fn polar_to_cartesian_with_speed(l: [f64; 6]) -> [f64; 6] {
    if l[3] == 0.0 && l[4] == 0.0 && l[5] == 0.0 {
        let pos = polar_to_cartesian([l[0], l[1], l[2]]);
        return [pos[0], pos[1], pos[2], 0.0, 0.0, 0.0];
    }
    let (sinlon, coslon) = l[0].sin_cos();
    let (sinlat, coslat) = l[1].sin_cos();
    let x0 = l[2] * coslat * coslon;
    let x1 = l[2] * coslat * sinlon;
    let x2 = l[2] * sinlat;
    let rxyz = l[2];
    let rxy = (x0 * x0 + x1 * x1).sqrt();
    let xx5 = l[5];
    let xx4 = l[4] * rxyz;
    let x5 = sinlat * xx5 + coslat * xx4;
    let xx3 = coslat * xx5 - sinlat * xx4;
    let xx4b = l[3] * rxy;
    let x3 = coslon * xx3 - sinlon * xx4b;
    let x4 = sinlon * xx3 + coslon * xx4b;
    [x0, x1, x2, x3, x4, x5]
}

pub fn cotrans(xpo: [f64; 3], eps: f64) -> [f64; 3] {
    let e = eps * DEGTORAD;
    let polar = [xpo[0] * DEGTORAD, xpo[1] * DEGTORAD, 1.0];
    let cart = polar_to_cartesian(polar);
    let rotated = rotate_x(cart, e);
    let result = cartesian_to_polar(rotated);
    [result[0] * RADTODEG, result[1] * RADTODEG, xpo[2]]
}

pub fn cotrans_with_speed(xpo: [f64; 6], eps: f64) -> [f64; 6] {
    let e = eps * DEGTORAD;
    let x = [
        xpo[0] * DEGTORAD, xpo[1] * DEGTORAD, 1.0,
        xpo[3] * DEGTORAD, xpo[4] * DEGTORAD, xpo[5],
    ];
    let cart = polar_to_cartesian_with_speed(x);
    let pos = rotate_x([cart[0], cart[1], cart[2]], e);
    let vel = rotate_x([cart[3], cart[4], cart[5]], e);
    let result = cartesian_to_polar_with_speed([
        pos[0], pos[1], pos[2], vel[0], vel[1], vel[2],
    ]);
    [
        result[0] * RADTODEG, result[1] * RADTODEG, xpo[2],
        result[3] * RADTODEG, result[4] * RADTODEG, xpo[5],
    ]
}
```

### Step 6: split_degrees

Uses `SplitDegFlags` from `src/flags.rs` (already defined, line 112). NAKSHATRA flag is silently ignored for now — the normal degree-splitting logic runs instead. Will be implemented when sidereal mode lands (swisseph-rs/9).

```rust
use crate::flags::SplitDegFlags;
use crate::types::DegreeParts;

pub fn split_degrees(mut ddeg: f64, flags: SplitDegFlags) -> DegreeParts {
    let mut sign = 1i32;
    if ddeg < 0.0 {
        sign = -1;
        ddeg = -ddeg;
    }
    let mut dadd = if flags.contains(SplitDegFlags::ROUND_DEG) {
        0.5
    } else if flags.contains(SplitDegFlags::ROUND_MIN) {
        0.5 / 60.0
    } else if flags.contains(SplitDegFlags::ROUND_SEC) {
        0.5 / 3600.0
    } else {
        0.0
    };
    if flags.contains(SplitDegFlags::KEEP_DEG) {
        if (ddeg + dadd) as i32 - ddeg as i32 > 0 {
            dadd = 0.0;
        }
    } else if flags.contains(SplitDegFlags::KEEP_SIGN) {
        if ddeg % 30.0 + dadd >= 30.0 {
            dadd = 0.0;
        }
    }
    ddeg += dadd;
    if flags.contains(SplitDegFlags::ZODIACAL) {
        sign = (ddeg / 30.0) as i32;
        if sign == 12 { sign = 0; }
        ddeg %= 30.0;
    }
    let degrees = ddeg as i32;
    ddeg -= degrees as f64;
    let minutes = (ddeg * 60.0) as i32;
    ddeg -= minutes as f64 / 60.0;
    let seconds = (ddeg * 3600.0) as i32;
    let second_fraction = if !flags.intersects(
        SplitDegFlags::ROUND_DEG | SplitDegFlags::ROUND_MIN | SplitDegFlags::ROUND_SEC,
    ) {
        ddeg * 3600.0 - seconds as f64
    } else {
        0.0
    };
    DegreeParts {
        degrees,
        minutes: if flags.contains(SplitDegFlags::ROUND_DEG) { 0 } else { minutes },
        seconds: if flags.intersects(SplitDegFlags::ROUND_DEG | SplitDegFlags::ROUND_MIN) {
            0
        } else {
            seconds
        },
        second_fraction,
        sign,
    }
}
```

